def unique_sorted(values):
    result = []
    for value in sorted(values):
        if value not in result:
            result.append(value)
    return result

def unique_sorted(values):
    ordered = sorted(values)
    unique = []
    for item in ordered:
        if not unique or unique[-1] != item:
            unique.append(item)
    return unique
